BEGIN TRANSACTION;
CREATE TABLE github_prs(pr_id TEXT PRIMARY KEY, service_name TEXT, param_name TEXT, author_handle TEXT, merged_at TEXT, summary TEXT);
CREATE TABLE microservices(service_name TEXT PRIMARY KEY, owner_handle TEXT, timeout_sec INTEGER, max_retries INTEGER, rate_limit_rpm INTEGER, batch_size_mb INTEGER, sla_hours INTEGER, circuit_breaker_pct INTEGER, updated_at TEXT, last_pr TEXT, evidence_id TEXT);
CREATE TABLE notion_pages(page_id TEXT PRIMARY KEY, service_name TEXT, param_name TEXT, title TEXT, updated_at TEXT, snippet TEXT);
CREATE TABLE production_incidents(incident_id TEXT PRIMARY KEY, service_name TEXT, started_at TEXT, resolved_at TEXT, root_cause_pr TEXT, penalty_rate_per_hour REAL, weight_kg REAL);
CREATE TABLE slack_messages(msg_id TEXT PRIMARY KEY, channel TEXT, service_name TEXT, param_name TEXT, author_handle TEXT, posted_at TEXT, text TEXT);
COMMIT;
